#include <stdio.h>

int recherche(int t[], int n, int x) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (t[mid] == x) return mid;
        else if (t[mid] < x) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

int main(void) {
    int t[] = {1, 3, 5, 7, 9};
    printf("%d\n", recherche(t, 5, 7));   /* 3 */
    return 0;
}

function recherche(t, x) {
  let low = 0, high = t.length - 1;
  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    if (t[mid] === x) return mid;
    else if (t[mid] < x) low = mid + 1;
    else high = mid - 1;
  }
  return -1;
}

console.log(recherche([1, 3, 5, 7, 9], 7));   // 3

public class Main {
    static int recherche(int[] t, int x) {
        int low = 0, high = t.length - 1;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (t[mid] == x) return mid;
            else if (t[mid] < x) low = mid + 1;
            else high = mid - 1;
        }
        return -1;
    }

    public static void main(String[] args) {
        int[] t = {1, 3, 5, 7, 9};
        System.out.println(recherche(t, 7));   // 3
    }
}

# tri par selection
# idea : chercher le plus petit, le mettre devant, recommencer

def tri(t):
    for i in range(len(t)):
        min_idx = i
        for j in range(i + 1, len(t)):
            if t[j] < t[min_idx]:
                min_idx = j
        t[i], t[min_idx] = t[min_idx], t[i]
    return t

