/* tri par selection : chercher le plus petit, le mettre devant */
int main(void) {
    int t[4] = {5, 2, 9, 1}, n = 4;
    for (int i = 0; i < n - 1; i++) {
        int min_idx = i;
        for (int j = i + 1; j < n; j++)
            if (t[j] < t[min_idx]) min_idx = j;
        int tmp = t[i]; t[i] = t[min_idx]; t[min_idx] = tmp;
    }
    for (int i = 0; i < n; i++) printf("%d ", t[i]);
    printf("\n");   /* 1 2 5 9 */
    return 0;
}

// tri par selection : chercher le plus petit, le mettre devant
function tri(t) {
  for (let i = 0; i < t.length; i++) {
    let minIdx = i;
    for (let j = i + 1; j < t.length; j++) {
      if (t[j] < t[minIdx]) minIdx = j;
    }
    [t[i], t[minIdx]] = [t[minIdx], t[i]];
  }
  return t;
}

console.log(tri([5, 2, 9, 1]));   // [1, 2, 5, 9]

import java.util.Arrays;

public class Main {
    // tri par selection : chercher le plus petit, le mettre devant
    static void tri(int[] t) {
        for (int i = 0; i < t.length - 1; i++) {
            int minIdx = i;
            for (int j = i + 1; j < t.length; j++) {
                if (t[j] < t[minIdx]) minIdx = j;
            }
            int tmp = t[i]; t[i] = t[minIdx]; t[minIdx] = tmp;
        }
    }

    public static void main(String[] args) {
        int[] t = {5, 2, 9, 1};
        tri(t);
        System.out.println(Arrays.toString(t));   // [1, 2, 5, 9]
    }
}

#include <stdio.h>

int factorielle(int n) {
    if (n <= 1) return 1;          /* cas de base */
    return n * factorielle(n - 1); /* pas de progression */
}

int main(void) {
    printf("%d\n", factorielle(5));   /* 120 */
    return 0;
}

