void ajouter(const char *nom, const char *tel) {
    strcpy(noms[nb], nom);
    strcpy(tels[nb], tel);
    nb++;
}

const char *chercher(const char *nom) {
    for (int i = 0; i < nb; i++)
        if (strcmp(noms[i], nom) == 0) return tels[i];
    return "inconnu";
}

int main(void) {
    ajouter("Alice", "0601");
    printf("%s\n", chercher("Alice"));   /* 0601 */
    printf("%s\n", chercher("Bob"));     /* inconnu */
    return 0;
}

